// Golden tests for ORIPA resources: LineType/GridType/FileType/ProjectKey/ProjectValue/
// RenderKey/Color/Constant. Goldens generated by tools/fixtures/core/resources.js from the
// reference JS implementation.
import Foundation
import ORIPACore

private struct ResourcesFixture: Decodable {
    struct LineTypes: Decodable {
        let values: [Int]
        let strings: [String?]
        let abbreviations: [String?]
        let colors: [[Double]?]
    }

    struct GridTypes: Decodable {
        let SQUARE: Int
        let TRIANGLE: Int
        let UNDEFINED: Int
    }

    struct FileTypeEntry: Decodable {
        let name: String
        let ordinal: Int
        let fileExtension: String
        let mime: String
        let valueOfKnowsName: Bool

        enum CodingKeys: String, CodingKey {
            case name, ordinal, mime, valueOfKnowsName
            case fileExtension = "extension"
        }
    }

    struct ProjectKeyEntry: Decodable {
        let name: String
        let ordinal: Int
        let key: String
    }

    struct ProjectValues: Decodable {
        let KEY_DIALOG: String
        let PROJECT_SUBDIRECTORY: String
        let REQUEST_CODE_PREVIEW: Int
        let RESULT_CODE_COPY: Int
        let RESULT_CODE_DELETE: Int
        let RESULT_CODE_NO_CHANGE: Int
        let RESULT_CODE_RENAME: Int
        let THUMBNAIL_SUBDIRECTORY: String
        let projectDirNoBase: String
        let projectDirBase: String
        let tempNoBase: String
        let tempBase: String
        let thumbNoBase: String
        let thumbBase: String
    }

    let lineTypes: LineTypes
    let gridTypes: GridTypes
    let fileTypes: [FileTypeEntry]
    let projectKeys: [ProjectKeyEntry]
    let renderKeys: [String: String]
    let renderKeyExamples: [[String]]
    let constants: [String: Double]
    let colorConstants: [String: [Double]]
    let projectValues: ProjectValues
}

private func floatConstant(_ name: String) -> Float? {
    switch name {
    case "ALPHA_FOLD_CP_XRAY_FACE": return Constant.ALPHA_FOLD_CP_XRAY_FACE
    case "ALPHA_FOLD_CP_XRAY_LINE_BOUNDARY": return Constant.ALPHA_FOLD_CP_XRAY_LINE_BOUNDARY
    case "ALPHA_FOLD_CP_XRAY_LINE_CREASE": return Constant.ALPHA_FOLD_CP_XRAY_LINE_CREASE
    case "LINE_HALF_WIDTH_DEFAULT_DP": return Constant.LINE_HALF_WIDTH_DEFAULT_DP
    case "LINE_HALF_WIDTH_DEFAULT_PX": return Constant.LINE_HALF_WIDTH_DEFAULT_PX
    case "LINE_HALF_WIDTH_FOLD_CP_OVERLAP_DP": return Constant.LINE_HALF_WIDTH_FOLD_CP_OVERLAP_DP
    case "LINE_HALF_WIDTH_FOLD_CP_OVERLAP_PX": return Constant.LINE_HALF_WIDTH_FOLD_CP_OVERLAP_PX
    case "LINE_HALF_WIDTH_GRID_DP": return Constant.LINE_HALF_WIDTH_GRID_DP
    case "LINE_HALF_WIDTH_MIRROR_DP": return Constant.LINE_HALF_WIDTH_MIRROR_DP
    case "LINE_WIDTH_DEFAULT": return Constant.LINE_WIDTH_DEFAULT
    case "LINE_WIDTH_FOLD_CP_BOUNDARY": return Constant.LINE_WIDTH_FOLD_CP_BOUNDARY
    case "LINE_WIDTH_FOLD_CP_CREASE": return Constant.LINE_WIDTH_FOLD_CP_CREASE
    case "LINE_WIDTH_FOLD_CP_CROSS": return Constant.LINE_WIDTH_FOLD_CP_CROSS
    case "LINE_WIDTH_FOLD_CP_CROSS_THICK": return Constant.LINE_WIDTH_FOLD_CP_CROSS_THICK
    case "LINE_WIDTH_SCREEN_DIVIDER": return Constant.LINE_WIDTH_SCREEN_DIVIDER
    case "MAX_SCALE_FACTOR": return Constant.MAX_SCALE_FACTOR
    case "MIN_SCALE_FACTOR": return Constant.MIN_SCALE_FACTOR
    case "POINT_SIZE_DEFAULT": return Constant.POINT_SIZE_DEFAULT
    case "POINT_SIZE_EMPHASIS": return Constant.POINT_SIZE_EMPHASIS
    case "SCREEN_TOUCH_RADIUS_DP": return Constant.SCREEN_TOUCH_RADIUS_DP
    case "SELECTION_RECT_DASH_LENGTH_DP": return Constant.SELECTION_RECT_DASH_LENGTH_DP
    default: return nil
    }
}

private func constantValue(_ name: String) -> Double? {
    if let floatValue = floatConstant(name) { return Double(floatValue) }
    if let intValue = intConstant(name) { return Double(intValue) }
    return nil
}

private func intConstant(_ name: String) -> Int? {
    switch name {
    case "SINGLE_GRID_IMAGE_DIMEN_DP": return Constant.SINGLE_GRID_IMAGE_DIMEN_DP
    case "SINGLE_LIST_IMAGE_DIMEN_DP": return Constant.SINGLE_LIST_IMAGE_DIMEN_DP
    case "TOUCH_CIRCLE_DURATION_MILLISECONDS": return Constant.TOUCH_CIRCLE_DURATION_MILLISECONDS
    default: return nil
    }
}

private func colorConstant(_ name: String) -> RGB? {
    switch name {
    case "COLOR_BOUNDARY": return Color.COLOR_BOUNDARY
    case "COLOR_VALLEY": return Color.COLOR_VALLEY
    case "COLOR_MOUNTAIN": return Color.COLOR_MOUNTAIN
    case "COLOR_FLAT": return Color.COLOR_FLAT
    case "COLOR_GRID": return Color.COLOR_GRID
    case "COLOR_SLICE": return Color.COLOR_SLICE
    case "COLOR_PICKED": return Color.COLOR_PICKED
    case "COLOR_ERROR": return Color.COLOR_ERROR
    case "COLOR_CP_POLYGON_FILL": return Color.COLOR_CP_POLYGON_FILL
    case "COLOR_TOUCH_CIRCLE": return Color.COLOR_TOUCH_CIRCLE
    case "COLOR_SELECTION_RECT": return Color.COLOR_SELECTION_RECT
    case "COLOR_XRAY_FACE": return Color.COLOR_XRAY_FACE
    case "COLOR_XRAY_CREASE": return Color.COLOR_XRAY_CREASE
    case "COLOR_XRAY_BOUNDARY": return Color.COLOR_XRAY_BOUNDARY
    case "COLOR_WIRE_CREASE": return Color.COLOR_WIRE_CREASE
    case "COLOR_WIRE_BOUNDARY": return Color.COLOR_WIRE_BOUNDARY
    default: return nil
    }
}

enum ResourcesTests {
    static var all: [TestSuite] {
        [TestSuite("CoreModel.Resources") { harness in
            let fixture = try Fixtures.decode(ResourcesFixture.self, "Fixtures/core/resources.json")

            // MARK: LineType constants + helper tables
            harness.expectEqual(LineType.getColor(1)?.components.count, 3, "getColor(1) components")
            harness.expectNil(LineType.getColor(7), "getColor(7) is nil")
            harness.expectNil(LineType.getColor(127), "getColor(127) is nil")
            for index in 0..<fixture.lineTypes.values.count {
                let raw = fixture.lineTypes.values[index]
                harness.expectEqual(LineType.getString(raw), fixture.lineTypes.strings[index], "getString(\(raw))")
                harness.expectEqual(LineType.getAbbreviation(raw), fixture.lineTypes.abbreviations[index], "getAbbreviation(\(raw))")
                let expectedColor = fixture.lineTypes.colors[index]
                let actualColor = LineType.getColor(raw)
                if let expectedColor {
                    harness.expectNotNil(actualColor, "getColor(\(raw))")
                    if let actualColor {
                        harness.expectEqual(Double(actualColor.r), expectedColor[0], "color r \(raw)")
                        harness.expectEqual(Double(actualColor.g), expectedColor[1], "color g \(raw)")
                        harness.expectEqual(Double(actualColor.b), expectedColor[2], "color b \(raw)")
                    }
                } else {
                    harness.expectNil(actualColor, "getColor(\(raw)) nil")
                }
            }
            // Typed enum helpers
            harness.expectEqual(LineType.mountain.getString(), "MOUNTAIN", "instance getString")
            harness.expectEqual(LineType.valley.getAbbreviation(), "va", "instance getAbbreviation")
            harness.expectEqual(LineType.undefined.getColor(), nil, "undefined color")
            harness.expectEqual(LineType(rawValue: 2), .mountain, "raw value mountain")
            harness.expectEqual(LineType.MOUNTAIN.rawValue, 2, "static alias")
            harness.expectEqual(LineType.FLAT.rawValue + LineType.UNDEFINED.rawValue, 127, "flat+undefined")

            // MARK: GridType
            harness.expectEqual(GridType.square.rawValue, fixture.gridTypes.SQUARE, "GridType.SQUARE")
            harness.expectEqual(GridType.triangle.rawValue, fixture.gridTypes.TRIANGLE, "GridType.TRIANGLE")
            harness.expectEqual(GridType.undefined.rawValue, fixture.gridTypes.UNDEFINED, "GridType.UNDEFINED")

            // MARK: FileType
            for fileType in fixture.fileTypes {
                guard let actual = FileType.valueOf(fileType.name) else {
                    harness.fail("FileType.valueOf(\(fileType.name))")
                    continue
                }
                harness.expectEqual(actual.ordinal, fileType.ordinal, "FileType ordinal \(fileType.name)")
                harness.expectEqual(actual.getExtension(), fileType.fileExtension, "FileType extension \(fileType.name)")
                harness.expectEqual(actual.getMimeType(), fileType.mime, "FileType mime \(fileType.name)")
                harness.expectEqual(actual.valueOf(text: fileType), fileType.valueOfKnowsName, "FileType identity \(fileType.name)")
            }
            harness.expectEqual(FileType.values().count, 5, "FileType.values count")
            harness.expectNil(FileType.valueOf("NOPE"), "unknown FileType")

            // MARK: ProjectKey
            for projectKey in fixture.projectKeys {
                guard let actual = ProjectKey.valueOf(projectKey.name) else {
                    harness.fail("ProjectKey.valueOf(\(projectKey.name))")
                    continue
                }
                harness.expectEqual(actual.ordinal, projectKey.ordinal, "ProjectKey ordinal")
                harness.expectEqual(actual.getKey(), projectKey.key, "ProjectKey key")
            }
            harness.expectEqual(ProjectKey.values().count, fixture.projectKeys.count, "ProjectKey count")

            // MARK: RenderKey
            harness.expectEqual(fixture.renderKeys.count, 22, "render key count")
            let renderKeySwitches: [(String, String)] = [
                ("CP_LINE_POSITION", RenderKey.CP_LINE_POSITION),
                ("CP_LINE_TYPE", RenderKey.CP_LINE_TYPE),
                ("CP_POINT_POSITION", RenderKey.CP_POINT_POSITION),
                ("CP_POINT_POSITION_ERROR", RenderKey.CP_POINT_POSITION_ERROR),
                ("BUNDLE_FOLD_OVERLAP", RenderKey.BUNDLE_FOLD_OVERLAP),
                ("BUNDLE_FOLD_OVERLAP_SPLIT", RenderKey.BUNDLE_FOLD_OVERLAP_SPLIT),
                ("BUNDLE_FOLD_XRAY_CROSS", RenderKey.BUNDLE_FOLD_XRAY_CROSS),
                ("OVERLAP_POSITION", RenderKey.OVERLAP_POSITION),
                ("OVERLAP_POSITION_REVERSE", RenderKey.OVERLAP_POSITION_REVERSE),
                ("OVERLAP_TYPE", RenderKey.OVERLAP_TYPE),
                ("XRAY_FACE_DRAW_ORDER", RenderKey.XRAY_FACE_DRAW_ORDER),
                ("XRAY_POINT_POSITION", RenderKey.XRAY_POINT_POSITION),
            ]
            for (name, value) in renderKeySwitches {
                harness.expectEqual(fixture.renderKeys[name], value, "render key \(name)")
            }
            for example in fixture.renderKeyExamples {
                harness.expectEqual(RenderKey.key(example[0]), example[1], "RenderKey.key(\(example[0]))")
            }

            // MARK: Constant
            harness.expectEqual(fixture.constants.count, 24, "constant count")
            for (name, expected) in fixture.constants {
                guard let actual = constantValue(name) else {
                    harness.fail("missing constant \(name)")
                    continue
                }
                harness.expectEqual(actual, expected, "Constant.\(name)")
            }

            // MARK: Color
            for (name, expected) in fixture.colorConstants {
                guard let actual = colorConstant(name) else {
                    harness.fail("missing color \(name)")
                    continue
                }
                harness.expectEqual(Double(actual.r), expected[0], "\(name).r")
                harness.expectEqual(Double(actual.g), expected[1], "\(name).g")
                harness.expectEqual(Double(actual.b), expected[2], "\(name).b")
            }
            harness.expectEqual(Color.COLOR_BOUNDARY.components.count, 3, "color components")

            // MARK: ProjectValue
            let projectValues = fixture.projectValues
            harness.expectEqual(ProjectValue.KEY_DIALOG, projectValues.KEY_DIALOG, "KEY_DIALOG")
            harness.expectEqual(ProjectValue.PROJECT_SUBDIRECTORY, projectValues.PROJECT_SUBDIRECTORY, "PROJECT_SUBDIRECTORY")
            harness.expectEqual(ProjectValue.REQUEST_CODE_PREVIEW, projectValues.REQUEST_CODE_PREVIEW, "REQUEST_CODE_PREVIEW")
            harness.expectEqual(ProjectValue.RESULT_CODE_COPY, projectValues.RESULT_CODE_COPY, "RESULT_CODE_COPY")
            harness.expectEqual(ProjectValue.RESULT_CODE_DELETE, projectValues.RESULT_CODE_DELETE, "RESULT_CODE_DELETE")
            harness.expectEqual(ProjectValue.RESULT_CODE_NO_CHANGE, projectValues.RESULT_CODE_NO_CHANGE, "RESULT_CODE_NO_CHANGE")
            harness.expectEqual(ProjectValue.RESULT_CODE_RENAME, projectValues.RESULT_CODE_RENAME, "RESULT_CODE_RENAME")
            harness.expectEqual(ProjectValue.THUMBNAIL_SUBDIRECTORY, projectValues.THUMBNAIL_SUBDIRECTORY, "THUMBNAIL_SUBDIRECTORY")
            harness.expectEqual(ProjectValue.getProjectDirectory(), projectValues.projectDirNoBase, "project dir no base")
            harness.expectEqual(ProjectValue.getProjectDirectory("/base"), projectValues.projectDirBase, "project dir base")
            harness.expectEqual(ProjectValue.getTempSaveFile(), projectValues.tempNoBase, "temp file no base")
            harness.expectEqual(ProjectValue.getTempSaveFile("/base"), projectValues.tempBase, "temp file base")
            harness.expectEqual(ProjectValue.getThumbDirectory(), projectValues.thumbNoBase, "thumb dir no base")
            harness.expectEqual(ProjectValue.getThumbDirectory("/base"), projectValues.thumbBase, "thumb dir base")
        }]
    }
}

private extension FileType {
    /// Helper for the golden flag that valueOf(name) round-trips to the same enum entry.
    func valueOf(text: ResourcesFixture.FileTypeEntry) -> Bool {
        FileType.valueOf(text.name) == self
    }
}
